(function() {
  const seen = new Set();
  window.CITIES = window.CITIES.filter(c => {
    const key = `${c.lat.toFixed(3)},${c.lon.toFixed(3)}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

  window.CITIES.sort((a, b) => b.pop - a.pop);
  window.CITIES = window.CITIES.slice(0, 1000);
})();
